<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class AICS_SEO_Plugin_Detector {public function active():array{$a=array();if(defined('WPSEO_VERSION')||class_exists('WPSEO_Options')){$a[]='yoast';}if(defined('RANK_MATH_VERSION')||class_exists('RankMath')){$a[]='rank_math';}if(defined('AIOSEO_VERSION')||class_exists('AIOSEO\\Plugin\\AIOSEO')){$a[]='aioseo';}return $a;}public function resolve(string $requested='auto'):array{$requested=sanitize_key($requested);$active=$this->active();$resolved='auto'===$requested?($active[0]??'native'):(in_array($requested,array('native','yoast','rank_math','aioseo'),true)?$requested:'native');if('native'!==$resolved&&!in_array($resolved,$active,true)){$resolved='native';}return array('key'=>$resolved,'active'=>$active,'multiple'=>count($active)>1,'warning'=>count($active)>1?'multiple_seo_plugins_active':'');}}
